#include "tree_common.hpp"
struct Geo{vector<LD>dist,iv,logs;uint64_t key;};
struct TGCache{const Grid&g;unordered_map<uint64_t,shared_ptr<Geo>>cache;deque<uint64_t>fifo;size_t bytes=0;TGCache(const Grid&gg):g(gg){} shared_ptr<Geo>get(const TreeSample&s){uint64_t key=0;for(int i=0;i<g.L;i++)key|=uint64_t(s.gapnodes[i])<<(3*i);auto it=cache.find(key);if(it!=cache.end())return it->second;auto out=make_shared<Geo>();out->key=key;int NE=g.L*(g.L+1)/2;size_t sz=(size_t)g.NP*NE;out->dist.resize(sz);out->iv.resize(sz);out->logs.resize(sz);LD node[40];for(int i=0;i<=g.N;i++)node[i]=i==0?1:(i==g.N?0:(1+cosl(acosl(-1.L)*i/g.N))/2);for(int p=0;p<g.NP;p++){LD ts[7],scale[7];ts[0]=scale[0]=1;for(int j=1;j<g.L;j++){ts[j]=node[g.idx[p][j-1]];scale[j]=scale[s.parents[j]]*ts[j];}int k=0;for(int a=0;a<=g.L;a++)for(int b=a+1;b<=g.L;b++){int lca=8;for(int j=a;j<b;j++)lca=min(lca,s.gapnodes[j]);LD q=0;for(int j=a;j<b;j++){int v=s.gapnodes[j];LD w=1;while(v!=lca){w*=ts[v];v=s.parents[v];}q+=w;}size_t z=(size_t)p*NE+k++;out->dist[z]=scale[lca]*q;out->iv[z]=1/sqrtl(q);out->logs[z]=.5L*logl(q);}}
 size_t now=sz*3*sizeof(LD);while(bytes+now>48*1024*1024ULL&&!fifo.empty()){auto k=fifo.front();fifo.pop_front();auto z=cache.find(k);bytes-=z->second->dist.size()*3*sizeof(LD);cache.erase(z);}bytes+=now;fifo.push_back(key);cache[key]=out;return out;}};
struct SWeights{vector<LD>v;vector<uint32_t>offset;vector<unsigned char>first;size_t bytes()const{return v.size()*sizeof(LD)+offset.size()*4+first.size();}};
struct TWCache{const Grid&g;unordered_map<uint64_t,shared_ptr<SWeights>>cache;deque<uint64_t>fifo;size_t bytes=0;TWCache(const Grid&gg):g(gg){}shared_ptr<SWeights>get(const TreeSample&s,const array<int,6>&b){uint64_t key=0;for(int j=0;j<g.D;j++)key|=uint64_t(b[j]+16*s.sizes[j+1])<<(7*j);auto it=cache.find(key);if(it!=cache.end())return it->second;auto out=make_shared<SWeights>();out->first.resize(g.NP);out->offset.resize(g.NP);out->v.reserve((size_t)g.NP*3);int K=7-g.L;for(int p=0;p<g.NP;p++){int start[6],nu=0;for(int j=0;j<g.D;j++){bool pole=g.wt(g.L-s.sizes[j+1],b[j],-1,g.idx[p][j])!=0;start[j]=pole?-1:0;nu+=pole;}int deg=K+nu;out->first[p]=g.D-nu;out->offset[p]=out->v.size();if(deg==0){LD val=1;for(int j=0;j<g.D;j++)val*=g.wt(g.L-s.sizes[j+1],b[j],0,g.idx[p][j]);out->v.push_back(val);continue;}LD a[7]={1};for(int j=0;j<g.D;j++){LD bb[7]={},v[7];for(int k=0;k<=deg;k++)v[k]=g.wt(g.L-s.sizes[j+1],b[j],start[j]+k,g.idx[p][j]);for(int k=0;k<=deg;k++)if(a[k])for(int r=0;k+r<=deg;r++)bb[k+r]+=a[k]*v[r];copy(bb,bb+7,a);}for(int j=0;j<=deg;j++)out->v.push_back(a[j]);}size_t now=out->bytes();while(bytes+now>96*1024*1024ULL&&!fifo.empty()){auto k=fifo.front();fifo.pop_front();auto z=cache.find(k);bytes-=z->second->bytes();cache.erase(z);}bytes+=now;fifo.push_back(key);cache[key]=out;return out;}};
array<LD,7>evalQuad(const OG&g,const Grid&grid,const TreeSample&s,TGCache&gc,TWCache&wc){int L=grid.L,n=L+1,NE=n*(n-1)/2,pos[8],index[8][8],map[28];for(int i=0;i<n;i++)pos[s.order[i]]=i;int k=0;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)index[a][b]=index[b][a]=k++;k=0;for(int a=0;a<n;a++)for(int b=a+1;b<n;b++)map[k++]=index[pos[a]][pos[b]];uint64_t inside[6]={};for(int j=0;j<L-1;j++){int k=0,sub=s.clusters[j+1];for(int a=0;a<n;a++)for(int b=a+1;b<n;b++,k++)if((sub>>a&1)&&(sub>>b&1))inside[j]|=1ULL<<(2*k);}auto geo=gc.get(s);array<LD,7>sum{};for(int ti=0;ti<(int)g.terms.size();ti++){auto&t=g.terms[ti];uint64_t key=g.g.terms[ti].key;array<int,6>b{};for(int j=0;j<L-1;j++)b[j]=__builtin_popcountll(key&inside[j])+2*__builtin_popcountll((key>>1)&inside[j]);auto ww=wc.get(s,b);for(int p=0;p<grid.NP;p++){auto*dd=&geo->dist[(size_t)p*NE];auto*iv=&geo->iv[(size_t)p*NE];auto*ll=&geo->logs[(size_t)p*NE];LD H=0,R=0,base=1,lv=0;for(auto&e:t.e){int k=map[e[0]],m=e[1];H+=m*dd[k];R+=e[2]*dd[k];LD v=iv[k];if(m==1)base*=v;else if(m==2)base*=v*v;else base*=v*v*v;lv+=m*ll[k];}if(!R)continue;if(H<=0)throw runtime_error("zero H");base*=R/H;int first=ww->first[p];auto*w=&ww->v[ww->offset[p]];if(first==6){sum[6]+=base*w[0];continue;}lv-=L*logl(H);LD ep[7];ep[0]=base;for(int j=1;j<7-first;j++)ep[j]=ep[j-1]*lv/j;for(int a=first;a<7;a++)for(int j=first;j<=a;j++)sum[a]+=w[j-first]*ep[a-j];}}
 array<LD,7>out{};for(int j=0;j<7;j++)for(int a=0;a<=j;a++)out[j]+=sum[a]*grid.gamma[j-a];return out;}

struct Shape{int n;shared_ptr<Shape>a,b;};
vector<shared_ptr<Shape>> shapes(int n){static map<int,vector<shared_ptr<Shape>>>cache;if(cache.count(n))return cache[n];vector<shared_ptr<Shape>>out;if(n==1)out.push_back(make_shared<Shape>(Shape{1,nullptr,nullptr}));else for(int k=1;k<n;k++)for(auto&a:shapes(k))for(auto&b:shapes(n-k))out.push_back(make_shared<Shape>(Shape{n,a,b}));return cache[n]=out;}
TreeSample exactTree(int L,const array<unsigned char,8>&vp,const shared_ptr<Shape>&shape){TreeSample t{};t.n=L+1;t.L=L;function<void(int,shared_ptr<Shape>,int)>go=[&](int st,shared_ptr<Shape>s,int parent){if(s->n==1){t.order[t.leafn++]=vp[st];return;}int id=t.nn++;t.parents[id]=parent;t.sizes[id]=s->n;for(int j=st;j<st+s->n;j++)t.clusters[id]|=1<<vp[j];go(st,s->a,id);t.gapnodes[t.ng++]=id;go(st+s->a->n,s->b,id);};go(0,shape,-1);return t;}

int main(int argc,char**argv){try{if(argc<9){cerr<<"root L degree samples_per_graph reps seed output selection [rate]\n";return 1;}string root=argv[1];int L=stoi(argv[2]),N=stoi(argv[3]),ns=stoi(argv[4]),B=stoi(argv[5]);uint64_t seed=stoull(argv[6]);string output=argv[7],sel=argv[8];LD rate=argc>9?stold(argv[9]):.8L;bool exact=argc>10&&string(argv[10])=="exact";auto vps=perms(L+1,true);auto shapeall=shapes(L+1);int Li;auto g0=load(root+"/L"+to_string(L)+"_coord.txt",Li);vector<OG>gs;int NE=L*(L+1)/2;for(auto&g:g0){OG og;og.g=g;for(auto&t:g.terms){OptTerm tt;for(int k=0;k<NE;k++)if(t.m[k])tt.e.push_back({k,t.m[k],t.co[k]});og.terms.push_back(tt);}gs.push_back(move(og));}vector<TP>props(gs.size());vector<int>counts(gs.size(),ns);{ifstream zf(root+"/exact_zero_L"+to_string(L)+".txt");int z;if(zf>>z)for(int j=0;j<z;j++){int id;zf>>id;counts[id]=0;}}for(int i=0;i<(int)gs.size();i++){auto&g=gs[i];if(g.terms.empty())counts[i]=0;if((sel=="power"&&!g.g.power)||(sel=="free"&&g.g.power))counts[i]=0;if(L==7&&abs(3*g.g.wb-g.g.wa)<1e-17L)counts[i]=0;if(counts[i])props[i]=prepTree(g,L,rate);}Grid grid(L,N,root,false);LD sign=L%2?1:-1;vector<vector<LD>>batches(B,vector<LD>(14));vector<vector<array<LD,14>>>per(B,vector<array<LD,14>>(gs.size()));double start=omp_get_wtime();
 #pragma omp parallel num_threads(2)
 {TGCache gc(grid);TWCache wc(grid);
 #pragma omp for schedule(dynamic)
 for(int ig=0;ig<B*(int)gs.size();ig++){int ib=ig/(int)gs.size(),gi=ig%(int)gs.size();int NN=counts[gi];if(!NN)continue;if(exact)NN=vps.size()*shapeall.size();auto&g=gs[gi];mt19937_64 rng(seed+0x9e3779b97f4a7c15ULL*(ib+1)+0xbf58476d1ce4e5b9ULL*(gi+1));array<LD,7>sum{};for(int it=0;it<NN;it++){LD u[16];for(int j=0;j<2*L-1;j++)u[j]=((LD)(rng()>>12)+.5L)/4503599627370496.L;auto s=exact?exactTree(L,vps[it/shapeall.size()],shapeall[it%shapeall.size()]):drawTree(props[gi],u);LD weight=exact?2.L*NN:props[gi].Z;if(!exact)for(int j=1;j<L;j++)weight*=s.alpha[j];auto val=evalQuad(g,grid,s,gc,wc);for(int j=0;j<7;j++)sum[j]+=weight*val[j]/NN;}for(int j=0;j<7;j++){per[ib][gi][j]=sign*g.g.wa*sum[j];per[ib][gi][7+j]=sign*g.g.wb*sum[j];}
 if(gi%50==49||gi==(int)gs.size()-1){
 #pragma omp critical
 cerr<<"rep "<<ib<<" graph "<<gi<<" sec "<<omp_get_wtime()-start<<"\n";}}}
 for(int ib=0;ib<B;ib++)for(auto&row:per[ib])for(int j=0;j<14;j++)batches[ib][j]+=row[j];
 ofstream out(output);out<<setprecision(24)<<"{\"L\":"<<L<<",\"N\":"<<N<<",\"samples_per_graph\":"<<ns<<",\"replicates\":"<<B<<",\"seed\":"<<seed<<",\"rate\":"<<rate<<",\"selection\":\""<<sel<<"\",\"method\":\"tree_quadrature\",\"seconds\":"<<omp_get_wtime()-start<<",\"batches\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<'[';for(int j=0;j<14;j++){if(j)out<<',';out<<batches[ib][j];}out<<']';}out<<"],\"graph_batches\":[";for(int ib=0;ib<B;ib++){if(ib)out<<',';out<<'[';for(int gi=0;gi<(int)gs.size();gi++){if(gi)out<<',';out<<'[';for(int j=0;j<14;j++){if(j)out<<',';out<<per[ib][gi][j];}out<<']';}out<<']';}out<<"]}\n";
 }catch(exception&e){cerr<<e.what()<<'\n';return 2;}}
